// A local stand-in for @prisma/client, backed by a JSON file, so the generated
// Prisma-native entitlement module can be EXECUTED in tests.
//
// It implements exactly the two raw-SQL entry points the generated code uses,
// $queryRawUnsafe and $executeRawUnsafe, over the handful of statement shapes
// Akeso emits. Values arrive as bound parameters, never interpolated, and the
// double asserts that: a statement carrying a literal quote where a parameter
// should be is rejected, because that is the bug a real database would let
// through silently.
import { readFile, writeFile } from "node:fs/promises";

const store = () => process.env.AKESO_FIXTURE_DB;
const load = async () => { try { return JSON.parse(await readFile(store(), "utf8")); } catch { return { tables: {} }; } };
const save = (db) => writeFile(store(), JSON.stringify(db, null, 2));
const unq = (s) => s.replace(/^"|"$/g, "");

export class PrismaClient {
  async $queryRawUnsafe(sql, ...params) {
    if (/'[^']*'/.test(sql)) throw new Error(`fixture: a literal string reached the database; values must be parameters: ${sql}`);
    const db = await load();
    let m;
    if ((m = sql.match(/^SELECT (.+) FROM "([^"]+)" WHERE "([^"]+)" = \$1 LIMIT 1$/))) {
      const rows = db.tables[unq(m[2])];
      if (!rows) throw new Error(`relation "${unq(m[2])}" does not exist`);
      const cols = m[1].split(",").map((c) => unq(c.trim()));
      const row = rows.find((r) => String(r[unq(m[3])]) === String(params[0]));
      return row ? [Object.fromEntries(cols.map((c) => [c, row[c] ?? null]))] : [];
    }
    if ((m = sql.match(/^SELECT (.+) FROM "([^"]+)"$/))) {
      const rows = db.tables[unq(m[2])];
      if (!rows) throw new Error(`relation "${unq(m[2])}" does not exist`);
      const cols = m[1].split(",").map((c) => unq(c.trim()));
      return rows.map((row) => Object.fromEntries(cols.map((c) => [c, row[c] ?? null])));
    }
    throw new Error(`fixture: unrecognised query shape: ${sql}`);
  }

  async $executeRawUnsafe(sql, ...params) {
    if (/'[^']*'/.test(sql)) throw new Error(`fixture: a literal string reached the database; values must be parameters: ${sql}`);
    const db = await load();
    let m;
    if ((m = sql.match(/^UPDATE "([^"]+)" SET "billing_entitled" = \$1 WHERE "id" = \$2 AND \("billing_entitled" IS NOT DISTINCT FROM \$3 OR "billing_entitled" IS NULL\)$/))) {
      const rows = db.tables[unq(m[1])] || [];
      let n = 0;
      for (const row of rows) {
        if (String(row.id) !== String(params[1])) continue;
        const current = row.billing_entitled ?? null;
        if (current !== null && Boolean(current) !== Boolean(params[2])) continue;
        row.billing_entitled = Boolean(params[0]); n += 1;
      }
      await save(db); return n;
    }
    if ((m = sql.match(/^INSERT INTO "akeso_processed_events" \("event_id", "event_type"\) VALUES \(\$1, \$2\) ON CONFLICT \("event_id"\) DO NOTHING$/))) {
      db.tables.akeso_processed_events ||= [];
      if (!db.tables.akeso_processed_events.some((r) => r.event_id === params[0])) db.tables.akeso_processed_events.push({ event_id: params[0], event_type: params[1] });
      await save(db); return 1;
    }
    if ((m = sql.match(/^INSERT INTO "akeso_event_watermarks" \("account_id", "last_event_created"\) VALUES \(\$1, \$2\) ON CONFLICT \("account_id"\) DO UPDATE SET "last_event_created" = EXCLUDED\."last_event_created", "updated_at" = now\(\)$/))) {
      db.tables.akeso_event_watermarks ||= [];
      const row = db.tables.akeso_event_watermarks.find((r) => r.account_id === params[0]);
      if (row) row.last_event_created = params[1]; else db.tables.akeso_event_watermarks.push({ account_id: params[0], last_event_created: params[1] });
      await save(db); return 1;
    }
    throw new Error(`fixture: unrecognised statement shape: ${sql}`);
  }
}
